from pathlib import Path

import numpy as np
import pandas as pd
from r_interface import CI_COLUMNS

if __name__ == "__main__":
    # See whether the results generated by the comparison on different platforms match
    folder = Path(__file__).resolve().parent

    linux_1 = pd.read_csv(folder / "pilot_results_linux_1/results.csv")
    linux_2 = pd.read_csv(folder / "pilot_results_linux_2/results.csv")

    # Keys by which the pairing is done (so we compare corresponding cases)
    pair_keys = [
        "rand_eff_dgp",
        "n_l3",
        "n_l2",
        "n_l1",
        "method",
        "stat",
        "replication_id",
    ]

    linux_1 = linux_1.sort_values(pair_keys).reset_index(drop=True)
    linux_2 = linux_2.sort_values(pair_keys).reset_index(drop=True)

    # Ensure bounds belong to identical experiments and replications.
    # This isn't really needed but just in case
    pd.testing.assert_frame_equal(
        linux_1[pair_keys],
        linux_2[pair_keys],
        check_dtype=False,
    )

    for column in [*CI_COLUMNS, "estimate"]:
        linux_values = linux_1[column].to_numpy()
        mac_values = linux_2[column].to_numpy()

        # Ensure construction failures occur in identical places.
        np.testing.assert_array_equal(
            np.isnan(linux_values),
            np.isnan(mac_values),
        )

        # Assert bounds are the same, with absolute tolerance 1e-10
        np.testing.assert_allclose(
            linux_values,
            mac_values,
            rtol=0,
            atol=1e-10,
            equal_nan=True,
        )

    print("Both runs match!")
